<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\CarrierOnboarding;use App\Support\Url;Auth::requireLogin();$uid=(int)Auth::user()['id'];if(!CarrierOnboarding::mayOnboard($uid)){http_response_code(403);exit('Carrier access is required.');}$profile=CarrierOnboarding::current($uid);if(!$profile){header('Location: '.Url::to('carrier/onboarding.php'));exit;}$pageTitle='Carrier Profile';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Carrier profile</h1><p><?=h($profile['owner_type']==='company'?$profile['display_name']:$profile['legal_name'])?></p></div><span class="badge"><?=h(ucfirst($profile['verification_status']))?></span></div><?php if(isset($_GET['created'])):?><div class="success">Carrier profile submitted to McCollins Operations.</div><?php endif;if($profile['case_status']==='rejected'):?><div class="error"><strong>Verification rejected.</strong><?php if($profile['findings']):?><br><?=nl2br(h($profile['findings']))?><?php endif;?></div><?php elseif($profile['case_status']==='pending'):?><div class="notice">Verification is pending. Fleet registration is not available until approval.</div><?php endif;?><div class="card"><dl class="definition"><dt>Carrier type</dt><dd><?=h(ucfirst($profile['owner_type']))?></dd><?php if($profile['owner_type']==='company'):?><dt>Registration</dt><dd><?=h($profile['registration_number'].' · '.$profile['registration_country'])?></dd><?php endif;?><dt>TIN</dt><dd><?=h($profile['tin_number'])?></dd><dt>Business licence</dt><dd><?=h($profile['business_license_number'])?><?=h($profile['business_license_expiry']?' · expires '.$profile['business_license_expiry']:'')?></dd><dt>Insurance</dt><dd><?=h($profile['insurance_provider'].' · '.$profile['insurance_policy_number'])?><?=h($profile['insurance_expiry']?' · expires '.$profile['insurance_expiry']:'')?></dd><dt>Verification</dt><dd><?=h($profile['case_status'])?></dd></dl></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
